const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define location and geometry
  const latitude = 50.332360;
  const longitude = -116.939238;
  const radiusKm = 60;

  const center = ee.Geometry.Point([longitude, latitude]);
  const roi = center.buffer(radiusKm * 1000); // Convert to meters

  // Define dates
  const date1Start = '2020-12-02';
  const date1End = '2020-12-03';
  const date2Start = '2020-12-05';
  const date2End = '2020-12-06';

  // Function to calculate cloud cover percentage from Sentinel-2 QA60
  function getCloudCoverPercent(dateStart, dateEnd, region, label) {
    const col = ee.ImageCollection('COPERNICUS/S2')
      .filterBounds(region)
      .filterDate(dateStart, dateEnd)
      .select(['QA60']);

    const size = col.size().getInfo();

    if (size === 0) {
      console.log(`${label}: No images found.`);
      return null;
    }

    // Get first image
    const img = col.first();
    const qa60 = img.select('QA60');

    // Cloud and cirrus bits (bits 10 and 11)
    const cloudBitMask = 1024; // 2^10
    const cirrusBitMask = 2048; // 2^11

    // Identify cloud pixels
    const cloudPixels = qa60.bitwiseAnd(cloudBitMask).neq(0)
      .or(qa60.bitwiseAnd(cirrusBitMask).neq(0));

    // Count cloud pixels
    const cloudCount = cloudPixels.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: region,
      scale: 1000,
      maxPixels: 1e9
    }).get('QA60').getInfo();

    // Count total pixels
    const totalCount = qa60.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: 1000,
      maxPixels: 1e9
    }).get('QA60').getInfo();

    if (!cloudCount || !totalCount || totalCount === 0) {
      console.log(`${label}: Invalid pixel count.`);
      return null;
    }

    const cloudPercent = (cloudCount / totalCount) * 100;
    console.log(`${label}: Images: ${size}, Cloud: ${cloudPercent.toFixed(2)}%, Pixels (total/cloud): ${totalCount}/${cloudCount}`);

    return cloudPercent;
  }

  // Get cloud cover for both dates
  const cloud2Dec = getCloudCoverPercent(date1Start, date1End, roi, 'Dec 2, 2020');
  const cloud5Dec = getCloudCoverPercent(date2Start, date2End, roi, 'Dec 5, 2020');

  // Validation and final answer
  if (cloud2Dec === null || cloud5Dec === null) {
    console.log('Unable to retrieve data for one or both dates.');
    console.log('C1');
    return;
  }

  if (cloud2Dec === undefined || cloud5Dec === undefined || 
      isNaN(cloud2Dec) || isNaN(cloud5Dec) ||
      cloud2Dec < 0 || cloud2Dec > 100 ||
      cloud5Dec < 0 || cloud5Dec > 100) {
    console.log('Invalid cloud cover calculation.');
    console.log('C3');
    return;
  }

  console.log(`Comparison: Dec 2: ${cloud2Dec.toFixed(2)}% vs Dec 5: ${cloud5Dec.toFixed(2)}%`);
  console.log(`Increase: ${(cloud5Dec - cloud2Dec).toFixed(2)}%`);

  if (cloud5Dec > cloud2Dec) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
